# delete ClusterRoleBinding app-admin-binding and ClusterRole admin-like-role
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata: {name: app-role-binding, namespace: insecure-app}
roleRef: {apiGroup: rbac.authorization.k8s.io, kind: Role, name: app-role}
subjects:
- {kind: ServiceAccount, name: app-sa, namespace: insecure-app}

apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: {name: insecure-app-default-deny-allow, namespace: insecure-app}
spec:
  podSelector: {matchLabels: {app: insecure-app}}
  policyTypes: [Ingress, Egress]
  ingress:
  - from:
    - namespaceSelector: {matchLabels: {kubernetes.io/metadata.name: ingress-nginx}}
    ports:
    - {protocol: TCP, port: 8080}
  egress:
  - to:
    - namespaceSelector: {matchLabels: {kubernetes.io/metadata.name: kube-system}}
    ports:
    - {protocol: UDP, port: 53}
    - {protocol: TCP, port: 53}

